  const resourceIdentifier = `${environment.BETTER_AUTH_URL}/api`;

  return betterAuth({
    appName: "Shui",
    basePath: "/api/auth",
    baseURL: environment.BETTER_AUTH_URL,
    database: drizzleAdapter(createDb(environment.DB), {
      provider: "sqlite",
      schema: authSchema,
      transaction: false,
    }),
    disabledPaths: ["/token"],
    emailAndPassword: {
      enabled: true,
