import "@better-auth/core/utils/redirect-uri";
import { InferOptionSchema, Session, User } from "better-auth/types";
import { GenericEndpointContext, LiteralString } from "@better-auth/core";
//#region src/schema.d.ts
declare const schema: {
  oauthClient: {
    modelName: string;
    fields: {
      clientId: {
        type: "string";
        unique: true;
        required: true;
      };
      clientSecret: {
        type: "string";
        required: false;
      };
      clientDiscoveryId: {
        type: "string";
        required: false;
      };
      disabled: {
        type: "boolean";
        defaultValue: false;
        required: false;
      };
      skipConsent: {
        type: "boolean";
        required: false;
      };
      enableEndSession: {
        type: "boolean";
        required: false;
      };
      subjectType: {
        type: "string";
        required: false;
      };
      scopes: {
        type: "string[]";
        required: false;
      };
      clientCredentialsScopes: {
        type: "string[]";
        required: false;
        defaultValue: never[];
      };
      userId: {
        type: "string";
        required: false;
        references: {
          model: string;
          field: string;
        };
        index: true;
      };
      createdAt: {
        type: "date";
        required: false;
      };
      updatedAt: {
        type: "date";
        required: false;
      };
      name: {
        type: "string";
        required: false;
      };
