        type: "string";
        required: false;
      };
      contacts: {
        type: "string[]";
        required: false;
      };
      tos: {
        type: "string";
        required: false;
      };
      policy: {
        type: "string";
        required: false;
      };
      softwareId: {
        type: "string";
        required: false;
      };
      softwareVersion: {
        type: "string";
        required: false;
      };
      softwareStatement: {
        type: "string";
        required: false;
      };
      redirectUris: {
        type: "string[]";
        required: true;
      };
      postLogoutRedirectUris: {
        type: "string[]";
        required: false;
      };
      backchannelLogoutUri: {
        type: "string";
        required: false;
      };
      backchannelLogoutSessionRequired: {
        type: "boolean";
        required: false;
      };
      tokenEndpointAuthMethod: {
        type: "string";
        required: false;
      };
      applicationType: {
        type: "string";
        required: false;
      };
      jwks: {
        type: "string";
        required: false;
      };
      jwksUri: {
        type: "string";
        required: false;
      };
      grantTypes: {
        type: "string[]";
        required: false;
      };
      responseTypes: {
        type: "string[]";
        required: false;
      };
      requirePKCE: {
        type: "boolean";
        required: false;
      };
      dpopBoundAccessTokens: {
        type: "boolean";
        required: false;
        defaultValue: false;
      };
      referenceId: {
        type: "string";
        required: false;
      };
      metadata: {
        type: "json";
        required: false;
      };
    };
  };
  /**
   * A protected resource the AS issues access tokens for.
   *
   * Promotes protected resources into a first-class persisted entity with
   * per-resource token policy. A null value
   * on any policy column means "inherit the plugin-level default at token
   * issuance time" — admins can later override without re-seeding.
   *
   * @see RFC 8707 (Resource Indicators) — `identifier` is the `resource` parameter value
   * @see RFC 9068 §2.2 — `customClaims` cannot override reserved JWT claims (enforced server-side)
   */
  oauthResource: {
    modelName: string;
    fields: {
      identifier: {
        type: "string";
        required: true;
        unique: true;
      };
      name: {
        type: "string";
        required: true;
      };
      accessTokenTtl: {
        type: "number";
        required: false;
      };
      refreshTokenTtl: {
        type: "number";
        required: false;
      };
      signingAlgorithm: {
        type: "string";
        required: false;
      };
      signingKeyId: {
        type: "string";
        required: false;
      };
      allowedScopes: {
        type: "string[]";
        required: false;
      };
      customClaims: {
        type: "json";
        required: false;
      };
      dpopBoundAccessTokensRequired: {
        type: "boolean";
        required: false;
        defaultValue: false;
      };
      disabled: {
        type: "boolean";
        required: false;
        defaultValue: false;
      };
      createdAt: {
        type: "date";
        required: false;
      };
      updatedAt: {
        type: "date";
        required: false;
      };
      policyVersion: {
        type: "number";
        required: false;
        defaultValue: number;
      };
      metadata: {
        type: "json";
        required: false;
      };
    };
  };
  /**
   * Join table — which clients are allowed to request which resources.
   *
   * Authoritative only when `enforcePerClientResources: true` on plugin options.
   * When the flag is off, clients implicitly have access to all enabled resources
   * (preserves pre-entity behavior).
   *
   * Composite uniqueness on `(clientId, resourceId)` is load-bearing — the
   * `enforcePerClientResources` linkage check assumes one row per pair.
   *
   * Concurrent inserts of the same pair surface as a UNIQUE-constraint
   * error which the endpoint catches and converts to a 200 "alreadyLinked"
   * response (idempotency).
   */
  oauthClientResource: {
    modelName: string;
    fields: {
      clientId: {
        type: "string";
        required: true;
        references: {
          model: string;
          field: string;
          onDelete: "cascade";
        };
        index: true;
      };
      resourceId: {
        type: "string";
        required: true;
        references: {
          model: string;
          field: string;
          onDelete: "cascade";
        };
        index: true;
      };
      metadata: {
        type: "json";
        required: false;
      };
      createdAt: {
        type: "date";
        required: false;
