  oauthRefreshToken: {
    fields: {
      token: {
        type: "string";
        required: true;
        unique: true;
      };
      clientId: {
        type: "string";
        required: true;
        references: {
          model: string;
          field: string;
        };
        index: true;
      };
      sessionId: {
        type: "string";
        required: false;
        references: {
          model: string;
          field: string;
          onDelete: "set null";
        };
        index: true;
      };
      userId: {
        type: "string";
        required: true;
        references: {
          model: string;
          field: string;
        };
        index: true;
      };
      referenceId: {
        type: "string";
        required: false;
      };
      authorizationCodeId: {
        type: "string";
        required: false;
        index: true;
      };
      resources: {
        type: "string[]";
        required: false;
      };
      requestedUserInfoClaims: {
        type: "string[]";
        required: false;
      };
      expiresAt: {
        type: "date";
      };
      createdAt: {
        type: "date";
      };
      revoked: {
        type: "date";
        required: false;
      };
      rotatedAt: {
        type: "date";
        required: false;
      };
      rotationReplayResponse: {
        type: "string";
        required: false;
      };
      rotationReplayExpiresAt: {
        type: "date";
        required: false;
      };
      authTime: {
        type: "date";
        required: false;
      };
      confirmation: {
        type: "json";
        required: false;
      };
      scopes: {
        type: "string[]";
        required: true;
      };
    };
  };
  /**
   * An opaque access token sent when there is no resource audience claim
   * to assigned to the JWT.
   *
   * Access tokens are linked to a session, better-auth
   * authors SHALL always check for valid session!
   *
   * AccessTokens SHALL only be created at refresh,
   * destroyed at revoke, and read at introspection.
   * NEVER update an access token! Typically a refresh and
   * revoke (if not expired) may want to occur at the same time.
   */
  oauthAccessToken: {
    modelName: string;
    fields: {
      token: {
        type: "string";
        unique: true;
      };
      clientId: {
        type: "string";
        required: true;
        references: {
          model: string;
          field: string;
        };
        index: true;
      };
      sessionId: {
        type: "string";
        required: false;
        references: {
          model: string;
          field: string;
          onDelete: "set null";
        };
